import React, { useState } from 'react';
import Navbar from './Navbar'; // Importing the Navbar component

import './Weather.css'; // New CSS file for additional styling
import background from './assets/background.jpg'; // Replace with your desired background image

export default function App() {
  const [location, setLocation] = useState('');
  const [weatherData, setWeatherData] = useState(null);
  const [error, setError] = useState('');

  const fetchWeather = async () => {
    console.log("Fetching weather data for:", location); // Log the location being fetched
    if (!location) return;
    const apiKey = 'f18a7a5d00d70d74d79c528ce36980d3'; // Replace with your OpenWeatherMap API key
    const url = `https://api.openweathermap.org/data/2.5/weather?q=${location}&appid=${apiKey}&units=metric`;

    try {
      const response = await fetch(url);
      if (!response.ok) {
        throw new Error('Failed to fetch weather data');
      }
      const data = await response.json();
      console.log("Weather data received:", data); // Log the received weather data
      setWeatherData(data);
      setError('');
    } catch (err) {
      setError(err.message);
      console.error("Error fetching weather data:", err); // Log the error message
      setWeatherData(null);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    fetchWeather();
  };

  return (
    <div className="App">

      <Navbar />
      <div className='background-img'>
          <h1>Wheather App</h1>


      </div>



        <form onSubmit={handleSubmit}   style={{
    display: 'flex',
    justifyContent: 'center',
    marginBottom: '20px',
    backgroundColor: 'aquamarine', // Sets the background color
    padding: '10px', // Adds some spacing inside the form
    borderRadius: '5px', // Rounds the corners slightly
  }}>
          <input
            type="text"
            value={location}
            onChange={(e) => setLocation(e.target.value)}
            placeholder="Enter location"
            style={{ marginRight: '10px' }}
          />
          <button type="submit" className="submit-button">Get Weather</button>
        </form>
        {error && <p className="error-message">{error}</p>}
        {weatherData && (
          <div className="weather-card">
            <h2>{weatherData.name}</h2>
            <p>Temperature: {weatherData.main.temp} °C</p>
            <p>Humidity: {weatherData.main.humidity}%</p>
            <p>Wind Speed: {weatherData.wind.speed} m/s</p>
            <p>Conditions: {weatherData.weather[0].description}</p>
            <img src={`http://openweathermap.org/img/wn/${weatherData.weather[0].icon}.png`} alt="weather icon" />
          </div>
        )}

    </div>
  );
}
