import React from 'react';
import './Weather.css'; // Importing the same CSS for styling
import logo from './assets/logo.png'; // Replace with your desired logo
const Navbar = () => {
  return (
    <nav className="navbar">
      <h1 className="navbar-title">
  <img src={logo} width={50} alt="Weather App Logo" className="logo" />
</h1>
      <div className="navbar-links">
        <a href="#home" className="navbar-link">Home</a>
        <a href="#favorites" className="navbar-link">Favorites</a>
        <a href="#about" className="navbar-link">About</a>
      </div>
    </nav>
  );
};

export default Navbar;
